// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        vm.startPrank(address(0x1));
        c.initialize();
        vm.stopPrank();

        c.programOperators(address(0x1));
        vm.prank(address(0x2));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(0x3)));
        assertTrue(!ok, "Reference should revert, bug should allow");
    }
}
